const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { test } = require('node:test');
const { JSDOM, VirtualConsole } = require('jsdom');
const html = fs.readFileSync(path.join(__dirname, '..', 'index.html'), 'utf8');
const source = fs.readFileSync(path.join(__dirname, '..', 'app.js'), 'utf8');
const response = (body, status = 200) => ({ ok: status >= 200 && status < 300, status, headers: { get: (name) => name === 'X-Source-Revision' ? 'a'.repeat(64) : name === 'X-Dataset-ID' ? 'demo' : null }, json: async () => structuredClone(body), blob: async () => new Blob(['customer_id,orders\nc1,2']) });
const tick = async () => { for (let i = 0; i < 5; i++) await new Promise(setImmediate); };
function payload() { return { business: { id: 'b1', name: 'Harbor & Pine', currency: 'USD', timezone: 'UTC' }, source: { label: 'Fictional POS demo', revision: 'a'.repeat(64), dataset_id: 'demo', synthetic: true, coverage_start: '2026-08-16', coverage_end: '2026-11-14', as_of: '2026-11-14', segment_as_of: '2026-11-14', limitations: ['Observed data is incomplete.'] }, period: { start: '2026-10-16', end: '2026-11-14' }, metrics: { net_revenue_cents: 250000, gross_revenue_cents: 260000, refund_cents: 10000, order_count: 100, active_customers: 2, returning_customers: 1, returning_share: .5, average_order_cents: 2500, gross_average_order_cents: 2600, within_period_repeat_customers: 1, within_period_repeat_share: .5 }, trend: [{ date: '2026-10-16', net_revenue_cents: 100000, orders: 40 }, { date: '2026-11-14', net_revenue_cents: 150000, orders: 60 }], segments: [{ id: 'champions', label: 'Champions', description: 'Frequent recent buyers', customers: 1, revenue_cents: 200000 }, { id: 'slipping', label: 'Slipping away', description: 'Longer purchase gap', customers: 1, revenue_cents: 50000 }], customers: [{ id: 'c1', label: 'Customer 001', first_seen: '2026-08-16', last_seen: '2026-11-14', orders: 8, revenue_cents: 200000, segment: 'champions', days_since_last: 0 }, { id: 'c2', label: 'Customer 002', first_seen: '2026-09-01', last_seen: '2026-10-18', orders: 2, revenue_cents: 50000, segment: 'slipping', days_since_last: 27 }], cohorts: [{ month: '2026-10', customers: 2, retention: [1, .5, null, null] }], actions: [{ id: 'a1', title: 'Invite a familiar face back', reason: 'One observed regular has a longer purchase gap.', segment: 'slipping', customers: 1, metric: 'Return visits', suggestion: 'Test an invitation with an explicit comparison group.' }], definitions: { returning_share: 'Customers with purchases before the selected window.' } }; }
function boot(t, handler = () => response(payload())) {
  const dom = new JSDOM(html, { url: 'http://localhost/', runScripts: 'outside-only', virtualConsole: new VirtualConsole() });
  const calls = [], downloads = [], copies = []; Object.defineProperty(dom.window.navigator, 'clipboard', { value: { writeText: async (text) => { copies.push(text); } } }); dom.window.fetch = async (url, options) => { calls.push({ url, options }); return handler(url, options, calls.length); };
  dom.window.URL.createObjectURL = () => 'blob:export'; dom.window.URL.revokeObjectURL = () => {}; dom.window.HTMLAnchorElement.prototype.click = function () { downloads.push({ href: this.href, filename: this.download }); };
  dom.window.eval(source); t.after(() => dom.window.close());
  return { window: dom.window, calls, downloads, copies, get: (id) => dom.window.document.getElementById(id), click: (id) => dom.window.document.getElementById(id).click(), submit: (id) => dom.window.document.getElementById(id).dispatchEvent(new dom.window.Event('submit', { bubbles: true, cancelable: true })), change: (id, value, event = 'change') => { const node = dom.window.document.getElementById(id); node.value = value; node.dispatchEvent(new dom.window.Event(event, { bubbles: true })); } };
}
test('renders the owner snapshot, source label, metrics and unavailable cohorts', async (t) => { const app = boot(t); await tick(); assert.equal(app.get('dashboard-content').hidden, false); assert.equal(app.get('metric-revenue').textContent, '$2,500.00'); assert.equal(app.get('metric-returning').textContent, '50%'); assert.equal(app.get('source-pill').textContent, 'Synthetic demo'); assert.match(app.get('cohorts').textContent, /100%50%——/); assert.equal(app.get('customers').children.length, 2); assert.match(app.get('revenue-chart').getAttribute('aria-label'), /\$2,500\.00/); assert.equal(app.calls[0].options.cache, 'no-store'); assert.equal(app.calls[0].options.redirect, 'error'); });
test('customer search and segment selection update visible rows', async (t) => { const app = boot(t); await tick(); app.change('customer-search', '002', 'input'); assert.equal(app.get('customers').children.length, 1); assert.match(app.get('customers').textContent, /Customer 002/); app.change('segment-filter', 'champions'); assert.equal(app.get('customer-empty').hidden, false); app.window.document.querySelector('[data-segment="slipping"]').click(); assert.equal(app.get('customers-panel').hidden, false); assert.equal(app.get('customer-search').value, ''); assert.equal(app.get('customers').children.length, 1); });
test('date submission sends exact range and invalid range makes no request', async (t) => { const app = boot(t); await tick(); app.change('start-date', '2026-11-01'); app.change('end-date', '2026-11-10'); app.submit('date-form'); await tick(); assert.match(app.calls.at(-1).url, /start=2026-11-01&end=2026-11-10/); const count = app.calls.length; app.change('start-date', '2026-11-12'); app.change('end-date', '2026-11-01'); app.submit('date-form'); await tick(); assert.equal(app.calls.length, count); assert.match(app.get('status').textContent, /on or after/); });
test('network error hides previous data and clears investigations', async (t) => { let fail = false; const app = boot(t, () => { if (fail) throw new Error('Network unavailable'); return response(payload()); }); await tick(); fail = true; app.click('refresh'); await tick(); assert.equal(app.get('dashboard-content').hidden, true); assert.match(app.get('status').textContent, /Network unavailable/); assert.equal(app.get('ask-result').hidden, true); });
test('late dashboard responses cannot overwrite newer data', async (t) => { let finish; const app = boot(t, (url, options, count) => count === 1 ? new Promise((resolve) => { finish = resolve; }) : response({ ...payload(), business: { ...payload().business, name: 'Latest snapshot' } })); app.submit('date-form'); await tick(); finish(response(payload())); await tick(); assert.equal(app.get('business-name').textContent, 'Latest snapshot'); });
test('401 requests memory-only access and lock clears protected view', async (t) => { const app = boot(t, (url, options) => options.headers.Authorization === 'Bearer owner-token' ? response(payload()) : response({}, 401)); await tick(); assert.equal(app.get('access-panel').hidden, false); app.get('access-token').value = 'owner-token'; app.submit('access-form'); await tick(); assert.equal(app.get('dashboard-content').hidden, false); assert.equal(app.get('access-token').value, ''); assert.equal(app.window.localStorage.length + app.window.sessionStorage.length, 0); app.click('lock-button'); assert.equal(app.get('dashboard-content').hidden, true); assert.equal(app.get('access-panel').hidden, false); app.click('refresh'); await tick(); assert.equal(app.calls.at(-1).options.headers.Authorization, undefined); });
test('untrusted business and customer strings are rendered as text', async (t) => { const data = payload(); data.business.name = '<img src=x onerror=alert(1)>'; data.customers[0].label = '<script>bad()</script>'; const app = boot(t, () => response(data)); await tick(); assert.equal(app.get('business-name').textContent, data.business.name); assert.equal(app.get('business-name').children.length, 0); assert.equal(app.get('customers').querySelector('script'), null); assert.match(app.get('customers').textContent, /<script>bad\(\)<\/script>/); });
test('questions include selected window and safely show evidence', async (t) => { const app = boot(t, (url) => url.endsWith('/ask') ? response({ answer: 'One group deserves attention.', status: 'answered', provider: 'deterministic', source: payload().source, period: payload().period, evidence: [{ customers: 1, net_revenue_cents: 50000 }], limitations: ['This is a rule, not a prediction.'] }) : response(payload())); await tick(); app.get('question').value = 'Who is slipping?'; app.submit('ask-form'); await tick(); assert.deepEqual(JSON.parse(app.calls.at(-1).options.body), { question: 'Who is slipping?', start: '2026-10-16', end: '2026-11-14' }); assert.equal(app.get('ask-result').hidden, false); assert.match(app.get('evidence').textContent, /\$500\.00/); assert.match(app.get('answer-limitations').textContent, /not a prediction/); });
test('question example fills without submitting and an unsaved experiment draft stays in this tab', async (t) => { const app = boot(t); await tick(); const count = app.calls.length; app.window.document.querySelector('[data-question]').click(); assert.ok(app.get('question').value); assert.equal(app.calls.length, count); app.click('view-experiments'); app.get('actions').querySelector('button').click(); assert.equal(app.get('draft-card').hidden, false); assert.match(app.get('draft-hypothesis').value, /comparison group/); assert.equal(app.window.localStorage.length + app.window.sessionStorage.length, 0); await tick(); assert.equal(app.calls.some((call) => call.options.method === 'POST'), false); });
test('CSV export uses selected period and authenticated fetch rather than token URL', async (t) => { const app = boot(t); await tick(); app.click('export-customers'); await tick(); assert.match(app.calls.at(-1).url, /export\.csv\?start=2026-10-16&end=2026-11-14/); assert.equal(app.downloads.length, 1); assert.equal(app.downloads[0].filename, 'regulars-customers-2026-10-16-2026-11-14.csv'); assert.equal(app.calls.at(-1).url.includes('token'), false); });
test('empty observation windows remain honest and usable', async (t) => { const data = payload(); data.customers = []; data.segments = []; data.cohorts = []; data.actions = []; data.trend = []; data.metrics.returning_share = null; const app = boot(t, () => response(data)); await tick(); assert.equal(app.get('metric-returning').textContent, '—'); assert.match(app.get('revenue-chart').textContent, /No observed revenue/); assert.match(app.get('actions').textContent, /no observed customers/); assert.equal(app.get('customer-empty').hidden, false); });
function importHandler(url, options) { if (url.endsWith('/status')) return response({ can_import: true }); if (url.endsWith('/datasets')) return response({ active_id: 'demo', datasets: [{ id: 'demo', business_name: 'Harbor & Pine', synthetic: true }, { id: 'imported', business_name: 'New Shop', synthetic: false }] }); if (url.endsWith('/import/preview')) return response({ preview_hash: 'a'.repeat(64), business_name: 'New Shop', orders: 2, completed_orders: 2, excluded_orders: 0, pending_orders: 0, cancelled_orders: 0, gross_revenue_cents: 2500, refund_cents: 0, net_revenue_cents: 2500, refunds: 0, customers: 1, coverage_start: '2026-11-01', coverage_end: '2026-11-14', warnings: ['Supplied history only.'] }); if (url.endsWith('/import/commit') || url.endsWith('/datasets/select')) return response({ dataset_id: 'imported', active_id: 'imported' }); return response(payload()); }
test('reviewed import commits only the exact previewed data and clears preview after edits', async (t) => { const app = boot(t, importHandler); await tick(); app.click('data-source-button'); await tick(); assert.equal(app.get('data-drawer').hidden, false); assert.equal(app.get('dataset-select').children.length, 2); app.change('import-business', 'New Shop', 'input'); app.change('import-csv', 'kind,id\norder,o1', 'input'); app.submit('import-form'); await tick(); assert.equal(app.get('import-preview').hidden, false); assert.match(app.get('import-summary').textContent, /Order rows2/); app.change('import-csv', 'kind,id\norder,o2', 'input'); assert.equal(app.get('import-preview').hidden, true); app.click('commit-import'); assert.equal(app.calls.some((call) => call.url.endsWith('/import/commit')), false); app.submit('import-form'); await tick(); app.click('commit-import'); await tick(); const commit = app.calls.find((call) => call.url.endsWith('/import/commit')); assert.deepEqual(JSON.parse(commit.options.body), { csv: 'kind,id\norder,o2', business_name: 'New Shop', synthetic: false, preview_hash: 'a'.repeat(64) }); assert.equal(app.get('import-preview').hidden, true); assert.equal(app.get('import-csv').value, ''); assert.match(app.get('data-source-status').textContent, /Imported successfully/); assert.equal(app.calls.at(-1).url, '/api/v1/owner/dashboard'); });
test('dataset switching selects explicitly and resets prior date range', async (t) => { const app = boot(t, importHandler); await tick(); app.click('data-source-button'); await tick(); app.change('dataset-select', 'imported'); assert.equal(app.calls.some((call) => call.url.endsWith('/datasets/select')), false); app.click('select-dataset'); await tick(); const request = app.calls.find((call) => call.url.endsWith('/datasets/select')); assert.deepEqual(JSON.parse(request.options.body), { dataset_id: 'imported' }); assert.equal(app.calls.at(-1).url, '/api/v1/owner/dashboard'); assert.match(app.get('data-source-status').textContent, /Dataset switched/); });
test('read-only workspace disables import and dataset mutation controls', async (t) => { const app = boot(t, (url, options) => url.endsWith('/status') ? response({ can_import: false }) : importHandler(url, options)); await tick(); app.click('data-source-button'); await tick(); assert.equal(app.get('preview-import').disabled, true); assert.equal(app.get('select-dataset').disabled, true); assert.match(app.get('data-source-status').textContent, /read-only/); });
