function comparisonPayload() { return { baseline: { period: { start: '2026-09-16', end: '2026-10-15' }, metrics: { net_revenue_cents: 200000 } }, current: { period: payload().period, metrics: payload().metrics }, delta_cents: 50000, change_fraction: .25, fully_covered: true, days_per_period: 30, groups: [{ id: 'continued', label: 'Purchased in both periods', customers: 2, baseline_cents: 200000, current_cents: 250000, delta_cents: 50000 }], contributors: [{ customer_id: 'c1', baseline_cents: 150000, current_cents: 200000, delta_cents: 50000 }], omitted_contributors: 1, omitted_delta_cents: 0, reconciled_delta_cents: 50000, source: payload().source, limitations: ['Observed changes do not establish causation.'] }; }
