test('editing dates cancels a pending dashboard, preserves drafts and keeps the applied snapshot usable', async (t) => {
  let finish, dashboardCalls = 0;
  const app = boot(t, (url) => {
    if (url.endsWith('/ask')) return response(answerWithEvidence([]));
    dashboardCalls++;
    if (dashboardCalls === 2) return new Promise((resolve) => { finish = resolve; });
    if (dashboardCalls === 3) { const data = payload(); data.period.start = '2026-11-05'; data.metrics.net_revenue_cents = 12300; return response(data); }
    return response(payload());
  });
  await tick(); app.change('start-date', '2026-11-01', 'input'); app.submit('date-form'); await tick();
  const pending = app.calls.at(-1); assert.match(pending.url, /start=2026-11-01/); assert.equal(app.get('dashboard-content').hidden, false); assert.equal(app.get('metric-revenue').textContent, '$2,500.00');
  app.change('start-date', '2026-11-05', 'input'); assert.equal(pending.options.signal.aborted, true); assert.equal(app.get('refresh').disabled, false);
  const oldResponse = payload(); oldResponse.period.start = '2026-11-01'; oldResponse.metrics.net_revenue_cents = 99900; finish(response(oldResponse)); await tick();
  assert.equal(app.get('start-date').value, '2026-11-05'); assert.equal(app.get('metric-revenue').textContent, '$2,500.00'); assert.equal(app.get('dashboard-content').hidden, false); assert.equal(app.get('period-status').hidden, false); assert.match(app.get('period-status').textContent, /not applied yet.*2026-10-16 to 2026-11-14/);
  app.get('question').value = 'Summarize the applied period'; app.submit('ask-form'); await tick(); assert.equal(JSON.parse(app.calls.at(-1).options.body).start, '2026-10-16'); assert.equal(app.get('ask-result').hidden, false);
  app.submit('date-form'); await tick(); assert.equal(app.get('start-date').value, '2026-11-05'); assert.equal(app.get('metric-revenue').textContent, '$123.00'); assert.equal(app.get('period-status').hidden, true); assert.equal(app.get('ask-result').hidden, true); assert.equal(app.get('refresh').disabled, false);
});

