const savedPilotId = 'd'.repeat(64);
function reviewedPilot(inputs, overrides = {}) { const calculated = pilotPayload({ segment: inputs.segment, proposed_audience_cap: inputs.max_customers, offer_cents: inputs.offer_cents, window_days: inputs.window_days, budget_cents: inputs.budget_cents, maximum_offer_cost_cents: 10 * inputs.offer_cents, within_budget: 10 * inputs.offer_cents <= inputs.budget_cents, feasible_pilot: 10 * inputs.offer_cents <= inputs.budget_cents, period: { start: inputs.start, end: inputs.end } }); return { ...calculated, source: payload().source, dataset_id: 'demo', inputs: { ...inputs }, reviewed_plan_hash: 'c'.repeat(64), ...overrides }; }
function savedPilotRecord(body, calculation) { return { schema_version: 1, calculator_version: 1, id: savedPilotId, created_at: '2026-11-14T16:00:00Z', status: 'saved_draft', title: body.title, hypothesis: body.hypothesis, measure: body.measure, business: payload().business, source: { ...payload().source, dataset_id: body.expected_dataset_id, revision: body.expected_revision }, period: { start: body.inputs.start, end: body.inputs.end }, inputs: body.inputs, reviewed_plan_hash: body.reviewed_plan_hash, calculation, notes: [] }; }
function durableHandler(store = { records: [], plan: null }, overrides = {}) { return (url, options) => {
  if (overrides.request) { const result = overrides.request(url, options, store); if (result !== undefined) return result; }
  if (url.endsWith('/status')) return response({ can_import: true, can_save_pilots: overrides.canSave !== false });
  if (url.endsWith('/experiments/plan')) { store.plan = reviewedPilot(JSON.parse(options.body), overrides.plan || {}); return response(store.plan); }
  if (url.endsWith('/pilots') && options.method === 'POST') { const body = JSON.parse(options.body); if (!store.records.length) store.records.push(savedPilotRecord(body, store.plan)); return response(store.records[0]); }
  if (url.includes('/pilots?')) { const offset = Number(new URL(url, 'http://localhost').searchParams.get('offset')); return response({ pilots: store.records.slice(offset, offset + 20).map((record) => ({ ...record, note_count: record.notes.length })), pagination: { offset, limit: 20, total: store.records.length, next_offset: offset + 20 < store.records.length ? offset + 20 : null } }); }
  if (url.endsWith('/notes')) { const record = store.records.find((item) => url.includes(item.id)), body = JSON.parse(options.body); let note = record.notes.find((item) => item.observed_on === body.observed_on && item.text === body.text); if (!note) { note = { schema_version: 1, id: 'e'.repeat(64), pilot_id: record.id, created_at: '2026-11-14T17:00:00Z', observed_on: body.observed_on, text: body.text, verification: 'owner_reported' }; record.notes.push(note); } return response(note); }
  if (url.includes('/pilots/')) return response(store.records.find((record) => url.endsWith(record.id)), store.records.some((record) => url.endsWith(record.id)) ? 200 : 404);
  return importHandler(url, options);
}; }
async function prepareSavableDraft(app) { app.click('view-experiments'); await tick(); app.click('manual-pilot'); app.change('draft-name', 'Synthetic QA return-visit pilot', 'input'); app.change('draft-hypothesis', 'Review a synthetic return-visit offer with a holdout.', 'input'); app.change('draft-measure', 'Compare observed return visit shares over 14 days.', 'input'); app.change('pilot-segment', 'slipping'); app.change('pilot-audience', '20', 'input'); app.submit('pilot-form'); await tick(); }

test('reviewed pilot saves exact calculation inputs and opens immutable source-bound evidence', async (t) => {
  const store = { records: [], plan: null }, app = boot(t, durableHandler(store)); await tick(); await prepareSavableDraft(app);
  assert.equal(app.get('save-pilot').disabled, false); app.click('save-pilot'); await tick();
  const request = app.calls.find((call) => call.url.endsWith('/pilots') && call.options.method === 'POST'), body = JSON.parse(request.options.body);
  assert.deepEqual(body.inputs, store.plan.inputs); assert.equal(body.expected_dataset_id, 'demo'); assert.equal(body.expected_revision, payload().source.revision); assert.equal(body.reviewed_plan_hash, store.plan.reviewed_plan_hash); assert.equal('idempotency_key' in body, false);
  assert.equal(app.get('saved-pilot-detail').hidden, false); assert.equal(app.get('saved-pilot-title').textContent, body.title); assert.match(app.get('saved-pilot-source').textContent, /Harbor & Pine.*Synthetic\/test records.*2026-10-16 to 2026-11-14/); assert.match(app.get('saved-pilot-calculation').textContent, /Maximum offer cost\$50\.00/); assert.equal(app.get('saved-pilot-hypothesis').textContent, body.hypothesis); assert.match(app.get('save-pilot-status').textContent, /Regulars has not assigned or contacted/);
  assert.equal(app.window.document.activeElement, app.get('saved-pilot-title')); assert.equal(app.get('saved-pilot-content').querySelector('input:not(#pilot-note-date), textarea:not(#pilot-note-text)'), null);
  app.click('close-saved-pilot'); assert.equal(app.window.document.activeElement, app.get('save-pilot')); assert.equal(app.get('saved-pilots').querySelectorAll('[data-saved-pilot-id]').length, 1);
});

